def-struct-hyp(
    Type.annotation(@d, Type.to(Type.prod(S@Topology.ctxt.S, S@Topology.ctxt.S), Real)),
    Topology.metric(d, S@Topology.ctxt.S),
    struct(
        member[colon](%非负性%, Logic.forall-typed(Type.pair(@x, @y), Type.prod(S@Topology.ctxt.S, S@Topology.ctxt.S), Le(0, Type.apply(d, Type.pair(x,y))))),
        member[colon](%正定性%, Logic.forall-typed(Type.pair(@x, @y), Type.prod(S@Topology.ctxt.S, S@Topology.ctxt.S), Logic.iff(Eq(0, Type.apply(d, Type.pair(x,y))), Eq(x, y)))),
        member[colon](%对称性%, Logic.forall-typed(@x, S@Topology.ctxt.S, Logic.forall-typed(@y, S@Topology.ctxt.S, Eq(Type.apply(d, Type.pair(x, y)), Type.apply(d, Type.pair(y, x)))))),
        member[colon](
            %次可加性 / 三角不等式%, Logic.forall-typed(
                @x, 
                S@Topology.ctxt.S, 
                Logic.forall-typed(
                    @y, 
                    S@Topology.ctxt.S, 
                    Logic.forall-typed(
                        @z, 
                        S@Topology.ctxt.S,
                        Le(Type.apply(d, Type.pair(x, z)), Add.add(Type.apply(d, Type.pair(x, y)), Type.apply(d, Type.pair(y, z))))
                    )
                )
            )
        )
    )
)
